"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[769],{171:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-08-clustering-em</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-8-кластеризация-и-em-алгоритм">Лабораторная\nработа 8. Кластеризация и EM-алгоритм</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 7</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 7: функционал качества кластеризации и метод\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\n(опр. 7.1), смеси распределений (опр. 7.4), EM-алгоритм (опр. 7.6) и его\nмонотонность (теорема 7.7), ответственности (опр. 7.8), иерархическая\nкластеризация и linkage (опр. 7.11); лекция 6: байесовское правило,\nгауссовские плотности</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно (части 1–3) + 4 ч самостоятельно</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Реализовать\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nи EM для смеси гауссиан, проверить монотонность правдоподобия из теоремы\n7.7; понять, что\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\n— предельный случай EM, и увидеть, какие структуры данных он в принципе\nне способен найти; научиться выбирать число кластеров при отсутствии\nметок и осознать, что у задачи кластеризации нет единственного\nправильного ответа.</p>\n<h2 id="что-нужно-сдать">Что нужно сдать</h2>\n<p>Заполненный ноутбук <code>lab08_student.ipynb</code>, в котором:</p>\n<ol>\n<li>выполнены все задания (ячейки с <code># TODO</code>), код\nзапускается сверху вниз без ошибок;</li>\n<li>под каждым заданием заполнены ячейки <strong>Вывод</strong> — своими\nсловами, не пересказ кода;</li>\n<li>в конце — раздел «Итоги работы» с ответами на контрольные\nвопросы;</li>\n<li>все графики подписаны (заголовок, оси, легенда).</li>\n</ol>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже). Отчёт с чужим вариантом не\nпринимается.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell markdown">\n<p>Кластеризация — задача <strong>обучения без учителя</strong>: ответов\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>y</mi><mi>i</mi></msub><annotation encoding="application/x-tex">y_i</annotation></semantics></math>\nнет. Это меняет всё, к чему мы привыкли в работах 1–7: нет ни\nэмпирического риска относительно истинных ответов, ни скользящего\nконтроля в прежнем смысле, ни однозначного критерия «правильности».\nПоэтому здесь особенно важно понимать, <strong>что именно</strong>\nоптимизирует каждый метод.</p>\n</div>\n<div id="cell002" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> stats</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> load_digits, load_iris, make_blobs, make_circles, make_moons</span>\n<span id="cb1-48"><a href="#cb1-48" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler</span>\n<span id="cb1-49"><a href="#cb1-49" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> (adjusted_mutual_info_score, adjusted_rand_score,</span>\n<span id="cb1-50"><a href="#cb1-50" aria-hidden="true" tabindex="-1"></a>                             silhouette_samples, silhouette_score)</span>\n<span id="cb1-51"><a href="#cb1-51" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span></code></pre></div>\n</div>\n<div id="cell003" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell004" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell005" class="cell markdown">\n<hr />\n<h1 id="часть-1-k-средних">Часть 1.\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних</h1>\n<p>Определение 7.1: минимизируется сумма квадратов расстояний до центров\nкластеров</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>C</mi><mo>,</mo><mi>μ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><munderover><mo>∑</mo><mrow><mi>k</mi><mo>=</mo><mn>1</mn></mrow><mi>K</mi></munderover><munder><mo>∑</mo><mrow><mi>i</mi><mo>∈</mo><msub><mi>C</mi><mi>k</mi></msub></mrow></munder><mo stretchy="false" form="postfix">∥</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>μ</mi><mi>k</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mspace width="0.278em"></mspace><mo>→</mo><mspace width="0.278em"></mspace><mrow><mi>min</mi><mo>⁡</mo></mrow><mi>.</mi></mrow><annotation encoding="application/x-tex">\nQ(C, \\mu) = \\sum_{k=1}^{K}\\sum_{i \\in C_k}\\|x_i - \\mu_k\\|^2 \\;\\longrightarrow\\; \\min .\n</annotation></semantics></math></p>\n<p>Алгоритм Ллойда чередует два шага, каждый из которых <strong>не\nувеличивает</strong>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>:</p>\n<ol>\n<li>при фиксированных центрах отнести каждый объект к ближайшему\nцентру;</li>\n<li>при фиксированном разбиении пересчитать центры как средние\nкластеров.</li>\n</ol>\n<p>Отсюда сходимость за конечное число шагов (значений\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>\nконечное число, и оно не растёт), но <strong>только к локальному\nминимуму</strong>.</p>\n<p>Реализуйте метод с двумя инициализациями: случайной и\n<code>k-means++</code>.</p>\n</div>\n<div id="cell006" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> kmeans_pp_init(X, K, generator):</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;k-means++: следующий центр выбирается с вероятностью ~ квадрату</span></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a><span class="co">    расстояния до ближайшего из уже выбранных.&quot;&quot;&quot;</span></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> kmeans(X, K, init<span class="op">=</span><span class="st">&quot;++&quot;</span>, n_iter<span class="op">=</span><span class="dv">200</span>, tol<span class="op">=</span><span class="fl">1e-10</span>, seed<span class="op">=</span><span class="dv">0</span>):</span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Алгоритм Ллойда: чередование «отнести к ближайшему центру» и</span></span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a><span class="co">    «пересчитать центры». Возвращает (метки, центры, история Q).&quot;&quot;&quot;</span></span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-11"><a href="#cb3-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-12"><a href="#cb3-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-13"><a href="#cb3-13" aria-hidden="true" tabindex="-1"></a>X_b, y_b <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">500</span>, centers<span class="op">=</span><span class="dv">4</span>, cluster_std<span class="op">=</span><span class="fl">1.1</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb3-14"><a href="#cb3-14" aria-hidden="true" tabindex="-1"></a>X_b <span class="op">=</span> StandardScaler().fit_transform(X_b)</span>\n<span id="cb3-15"><a href="#cb3-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-16"><a href="#cb3-16" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) сверьте своё Q и разбиение со sklearn.cluster.KMeans (ARI ~ 1.0);</span></span>\n<span id="cb3-17"><a href="#cb3-17" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) постройте график Q по итерациям -- он обязан убывать;</span></span>\n<span id="cb3-18"><a href="#cb3-18" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) по 60 запусков с каждой инициализацией (случайная и k-means++):</span></span>\n<span id="cb3-19"><a href="#cb3-19" aria-hidden="true" tabindex="-1"></a><span class="co">#          гистограммы итогового Q и доля запусков, попавших в лучший минимум.</span></span></code></pre></div>\n</div>\n<div id="cell007" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Убывает ли\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>\nмонотонно? Какая инициализация чаще попадает в хороший локальный минимум\nи почему? Зачем в <code>sklearn</code> параметр <code>n_init</code>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell008" class="cell markdown">\n<hr />\n<h1 id="часть-2-что-k-средних-не-умеет">Часть 2. Что\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nне умеет</h1>\n<p>Функционал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mo>∑</mo><mi>k</mi></msub><msub><mo>∑</mo><mrow><mi>i</mi><mo>∈</mo><msub><mi>C</mi><mi>k</mi></msub></mrow></msub><mo stretchy="false" form="postfix">∥</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>μ</mi><mi>k</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\sum_k\\sum_{i \\in C_k}\\|x_i - \\mu_k\\|^2</annotation></semantics></math>\nжёстко задаёт форму кластеров: разбиение по ближайшему центру — это\n<strong>диаграмма Вороного</strong>, то есть кластеры всегда выпуклые и\nразделены прямыми (гиперплоскостями). Кроме того, квадрат расстояния\nштрафует крупные кластеры сильнее, чем мелкие.</p>\n<p>Проверьте это на трудном случае вашего варианта:\n<code>variant[&quot;hard_case&quot;]</code>.</p>\n</div>\n<div id="cell009" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.cluster <span class="im">import</span> AgglomerativeClustering, DBSCAN, SpectralClustering</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> make_hard(case, n<span class="op">=</span><span class="dv">600</span>, seed<span class="op">=</span>RANDOM_STATE):</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Сгенерировать трудный для K-средних случай из вашего варианта.&quot;&quot;&quot;</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a>case <span class="op">=</span> variant[<span class="st">&quot;hard_case&quot;</span>]</span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте данные своего трудного случая и сравните на них пять методов:</span></span>\n<span id="cb4-11"><a href="#cb4-11" aria-hidden="true" tabindex="-1"></a><span class="co">#       K-средних, иерархическую с ward и single, DBSCAN, спектральную.</span></span>\n<span id="cb4-12"><a href="#cb4-12" aria-hidden="true" tabindex="-1"></a><span class="co">#       Нарисуйте разбиения и сведите в таблицу ARI, AMI и число найденных кластеров.</span></span></code></pre></div>\n</div>\n<div id="cell010" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Насколько плохо сработал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nна вашем случае и <strong>почему именно</strong> — какое свойство\nфункционала это объясняет? Какой метод справился и за счёт чего?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell011" class="cell markdown">\n<hr />\n<h1 id="часть-3-em-алгоритм-для-смеси-гауссиан">Часть 3. EM-алгоритм для\nсмеси гауссиан</h1>\n<p>Определение 7.4: плотность смеси\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msubsup><mo>∑</mo><mrow><mi>k</mi><mo>=</mo><mn>1</mn></mrow><mi>K</mi></msubsup><msub><mi>w</mi><mi>k</mi></msub><mspace width="0.167em"></mspace><msub><mi>p</mi><mi>k</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">p(x) = \\sum_{k=1}^{K} w_k\\, p_k(x)</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mo>∑</mo><mi>k</mi></msub><msub><mi>w</mi><mi>k</mi></msub><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">\\sum_k w_k = 1</annotation></semantics></math>.\nПрямая максимизация правдоподобия по всем параметрам сложна из-за\nлогарифма суммы; EM (опр. 7.6) вводит скрытые переменные и чередует:</p>\n<p><strong>E-шаг</strong> — ответственности (опр. 7.8):\n<math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>γ</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub><mo>=</mo><mfrac><mrow><msub><mi>w</mi><mi>k</mi></msub><mspace width="0.167em"></mspace><msub><mi>p</mi><mi>k</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><mrow><munder><mo>∑</mo><mi>s</mi></munder><msub><mi>w</mi><mi>s</mi></msub><mspace width="0.167em"></mspace><msub><mi>p</mi><mi>s</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow></mfrac><mo>;</mo></mrow><annotation encoding="application/x-tex">\n\\gamma_{ik} = \\frac{w_k\\, p_k(x_i)}{\\sum_{s} w_s\\, p_s(x_i)} ;\n</annotation></semantics></math></p>\n<p><strong>M-шаг</strong> — пересчёт параметров как взвешенных оценок:\n<math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>w</mi><mi>k</mi></msub><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>γ</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub><mo>,</mo><mspace width="2.0em"></mspace><msub><mi>μ</mi><mi>k</mi></msub><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>γ</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub><msub><mi>x</mi><mi>i</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>γ</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub></mrow></mfrac><mo>,</mo><mspace width="2.0em"></mspace><msub><mi mathvariant="normal">Σ</mi><mi>k</mi></msub><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>γ</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>μ</mi><mi>k</mi></msub><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>μ</mi><mi>k</mi></msub><msup><mo stretchy="false" form="postfix">)</mo><mi>𝖳</mi></msup></mrow><mrow><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>γ</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub></mrow></mfrac><mi>.</mi></mrow><annotation encoding="application/x-tex">\nw_k = \\frac1\\ell\\sum_i \\gamma_{ik}, \\qquad\n\\mu_k = \\frac{\\sum_i \\gamma_{ik} x_i}{\\sum_i \\gamma_{ik}}, \\qquad\n\\Sigma_k = \\frac{\\sum_i \\gamma_{ik}(x_i - \\mu_k)(x_i - \\mu_k)^{\\mathsf T}}{\\sum_i \\gamma_{ik}} .\n</annotation></semantics></math></p>\n<p>Теорема 7.7: <strong>логарифм правдоподобия не убывает</strong> на\nкаждой итерации. Проверим это численно — это и есть главный эксперимент\nчасти.</p>\n<p>Тип ковариации задаётся вашим вариантом:\n<code>variant[&quot;gmm_cov&quot;]</code>.</p>\n</div>\n<div id="cell012" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> gmm_em(X, K, cov_type<span class="op">=</span><span class="st">&quot;full&quot;</span>, n_iter<span class="op">=</span><span class="dv">200</span>, tol<span class="op">=</span><span class="fl">1e-8</span>, seed<span class="op">=</span><span class="dv">0</span>, reg<span class="op">=</span><span class="fl">1e-6</span>):</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;EM для смеси гауссиан.</span></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a><span class="co">    E-шаг: gamma_ik = w_k p_k(x_i) / sum_s w_s p_s(x_i).</span></span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a><span class="co">           Считайте в ЛОГАРИФМАХ (logpdf + трюк вычитания максимума),</span></span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a><span class="co">           иначе при больших размерностях всё обнулится.</span></span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a><span class="co">    M-шаг: w_k = mean(gamma_k); mu_k, Sigma_k -- взвешенные оценки.</span></span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a><span class="co">           Для cov_type &#39;diag&#39; оставьте только диагональ, для &#39;spherical&#39; --</span></span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a><span class="co">           единичную матрицу, умноженную на среднюю дисперсию.</span></span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a><span class="co">    Возвращает (w, mu, Sigma, gamma, история logL).</span></span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb5-12"><a href="#cb5-12" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb5-13"><a href="#cb5-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-14"><a href="#cb5-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-15"><a href="#cb5-15" aria-hidden="true" tabindex="-1"></a>cov_type <span class="op">=</span> variant[<span class="st">&quot;gmm_cov&quot;</span>]</span>\n<span id="cb5-16"><a href="#cb5-16" aria-hidden="true" tabindex="-1"></a>X_g, y_g <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">600</span>, centers<span class="op">=</span><span class="dv">3</span>, cluster_std<span class="op">=</span><span class="fl">1.0</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb5-17"><a href="#cb5-17" aria-hidden="true" tabindex="-1"></a>X_g <span class="op">=</span> X_g <span class="op">@</span> np.array([[<span class="fl">0.6</span>, <span class="op">-</span><span class="fl">0.6</span>], [<span class="op">-</span><span class="fl">0.4</span>, <span class="fl">0.8</span>]])</span>\n<span id="cb5-18"><a href="#cb5-18" aria-hidden="true" tabindex="-1"></a>X_g <span class="op">=</span> StandardScaler().fit_transform(X_g)</span>\n<span id="cb5-19"><a href="#cb5-19" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-20"><a href="#cb5-20" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) обучите свой EM, выведите историю logL и ПРОВЕРЬТЕ, что все приросты</span></span>\n<span id="cb5-21"><a href="#cb5-21" aria-hidden="true" tabindex="-1"></a><span class="co">#          неотрицательны (теорема 7.7);</span></span>\n<span id="cb5-22"><a href="#cb5-22" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) сверьтесь с sklearn.mixture.GaussianMixture по logL на объект и по ARI;</span></span>\n<span id="cb5-23"><a href="#cb5-23" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) нарисуйте кластеры и эллипсы уровня ковариаций каждой компоненты;</span></span>\n<span id="cb5-24"><a href="#cb5-24" aria-hidden="true" tabindex="-1"></a><span class="co">#          прозрачностью точки покажите max_k gamma_ik -- уверенность отнесения.</span></span></code></pre></div>\n</div>\n<div id="cell013" class="cell markdown">\n<h3 id="задание-32-k-средних-как-предельный-случай-em">Задание 3.2.\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nкак предельный случай EM</h3>\n<p>Возьмём смесь со сферическими ковариациями\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi mathvariant="normal">Σ</mi><mi>k</mi></msub><mo>=</mo><msup><mi>σ</mi><mn>2</mn></msup><mi>I</mi></mrow><annotation encoding="application/x-tex">\\Sigma_k = \\sigma^2 I</annotation></semantics></math>\nи устремим\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>σ</mi><mo>→</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\sigma \\to 0</annotation></semantics></math>.\nОтветственности\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>γ</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub><mo>∝</mo><msub><mi>w</mi><mi>k</mi></msub><mrow><mi>exp</mi><mo>⁡</mo></mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mi>−</mi><mo stretchy="false" form="postfix">∥</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>μ</mi><mi>k</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mi>/</mi><mo stretchy="false" form="prefix">(</mo><mn>2</mn><msup><mi>σ</mi><mn>2</mn></msup><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\gamma_{ik} \\propto w_k \\exp\\bigl(-\\|x_i - \\mu_k\\|^2/(2\\sigma^2)\\bigr)</annotation></semantics></math>\nпревращаются в жёсткое отнесение к ближайшему центру, а M-шаг — в\nпересчёт средних. То есть\n<strong><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\n— это EM для сферической смеси в пределе нулевой дисперсии</strong>.</p>\n<p>Проверьте: посчитайте ответственности при убывающем\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>σ</mi><annotation encoding="application/x-tex">\\sigma</annotation></semantics></math>\nи сравните разбиение с результатом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних.</p>\n</div>\n<div id="cell014" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: возьмите центры, найденные K-средних, и для sigma из [1, 0.5, 0.2, 0.1, 0.05, 0.02]</span></span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       посчитайте ответственности сферической смеси; проследите, как средняя</span></span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       max-ответственность стремится к единице, а разбиение -- к разбиению K-средних.</span></span></code></pre></div>\n</div>\n<div id="cell015" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Подтвердилась ли монотонность правдоподобия?\nЧто происходит с ответственностями при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>σ</mi><mo>→</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\sigma \\to 0</annotation></semantics></math>?\nВ каких ситуациях мягкое отнесение предпочтительнее жёсткого?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell016" class="cell markdown">\n<hr />\n<h1 id="часть-4-выбор-числа-кластеров">Часть 4. Выбор числа\nкластеров</h1>\n<p>Меток нет, поэтому «правильное»\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>\nвыбирается косвенно. Три подхода (<code>variant[&quot;k_selection&quot;]</code>\nуказывает вашу пару):</p>\n<ul>\n<li><strong>метод локтя</strong>:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>K</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(K)</annotation></semantics></math>\nубывает всегда, ищут точку излома;</li>\n<li><strong>силуэт</strong>: для объекта\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>i</mi><annotation encoding="application/x-tex">i</annotation></semantics></math>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub><mo>=</mo><mstyle displaystyle="true"><mfrac><mrow><msub><mi>b</mi><mi>i</mi></msub><mo>−</mo><msub><mi>a</mi><mi>i</mi></msub></mrow><mrow><mrow><mi>max</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><msub><mi>a</mi><mi>i</mi></msub><mo>,</mo><msub><mi>b</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">s_i = \\dfrac{b_i - a_i}{\\max(a_i, b_i)}</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>a</mi><mi>i</mi></msub><annotation encoding="application/x-tex">a_i</annotation></semantics></math>\n— среднее расстояние внутри своего кластера,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>b</mi><mi>i</mi></msub><annotation encoding="application/x-tex">b_i</annotation></semantics></math>\n— до ближайшего чужого; хорошо, когда средний силуэт велик;</li>\n<li><strong>информационные критерии</strong> для смеси:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">A</mi><mi mathvariant="normal">I</mi><mi mathvariant="normal">C</mi></mrow><mo>=</mo><mi>−</mi><mn>2</mn><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>L</mi><mo>+</mo><mn>2</mn><mi>p</mi></mrow><annotation encoding="application/x-tex">\\mathrm{AIC} = -2\\ln L + 2p</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">B</mi><mi mathvariant="normal">I</mi><mi mathvariant="normal">C</mi></mrow><mo>=</mo><mi>−</mi><mn>2</mn><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>L</mi><mo>+</mo><mi>p</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>ℓ</mi></mrow><annotation encoding="application/x-tex">\\mathrm{BIC} = -2\\ln L + p\\ln \\ell</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>p</mi><annotation encoding="application/x-tex">p</annotation></semantics></math>\n— число параметров модели.</li>\n</ul>\n<p>Сравните их на данных, где истинное\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>\nизвестно, — и посмотрите, совпадут ли ответы.</p>\n</div>\n<div id="cell017" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>X_k, y_k <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">600</span>, centers<span class="op">=</span><span class="dv">4</span>, cluster_std<span class="op">=</span><span class="fl">1.15</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>X_k <span class="op">=</span> StandardScaler().fit_transform(X_k)</span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a>K_grid <span class="op">=</span> <span class="bu">range</span>(<span class="dv">2</span>, <span class="dv">11</span>)</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) для каждого K посчитайте Q (инерцию), средний силуэт, AIC и BIC</span></span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a><span class="co">#          для GaussianMixture, а также ARI с истинными метками (для контроля);</span></span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) выберите K каждым критерием (локоть -- максимум второй разности Q)</span></span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a><span class="co">#          и сравните с истинным K = 4;</span></span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) три графика: Q(K), силуэт(K), AIC и BIC(K);</span></span>\n<span id="cb7-10"><a href="#cb7-10" aria-hidden="true" tabindex="-1"></a><span class="co">#       4) силуэтная диаграмма для выбранного K.</span></span>\n<span id="cb7-11"><a href="#cb7-11" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;критерии вашего варианта:&quot;</span>, variant[<span class="st">&quot;k_selection&quot;</span>])</span></code></pre></div>\n</div>\n<div id="cell018" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпали ли ответы разных критериев с истинным\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">K = 4</annotation></semantics></math>?\nКакой критерий оказался наименее надёжным? Почему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>K</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(K)</annotation></semantics></math>\nнельзя минимизировать напрямую?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell019" class="cell markdown">\n<hr />\n<h1 id="часть-5-иерархическая-кластеризация">Часть 5. Иерархическая\nкластеризация</h1>\n<p>Определение 7.11: агломеративный алгоритм начинает с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>\nодноэлементных кластеров и на каждом шаге объединяет два ближайших.\nСпособ измерения расстояния между кластерами (linkage) определяет всё\nповедение:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mtable><mtr><mtd columnalign="right" style="text-align: right; padding-right: 0"><mtext mathvariant="normal">single:</mtext><mspace width="0.222em"></mspace></mtd><mtd columnalign="left" style="text-align: left; padding-left: 0"><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>U</mi><mo>,</mo><mi>V</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><munder><mi>min</mi><mrow><mi>u</mi><mo>∈</mo><mi>U</mi><mo>,</mo><mi>v</mi><mo>∈</mo><mi>V</mi></mrow></munder><mi>ρ</mi><mo stretchy="false" form="prefix">(</mo><mi>u</mi><mo>,</mo><mi>v</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo></mtd><mtd columnalign="right" style="text-align: right; padding-right: 0"><mtext mathvariant="normal">complete:</mtext><mspace width="0.222em"></mspace></mtd><mtd columnalign="left" style="text-align: left; padding-left: 0"><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>U</mi><mo>,</mo><mi>V</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><munder><mi>max</mi><mrow><mi>u</mi><mo>,</mo><mi>v</mi></mrow></munder><mi>ρ</mi><mo stretchy="false" form="prefix">(</mo><mi>u</mi><mo>,</mo><mi>v</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo></mtd></mtr><mtr><mtd columnalign="right" style="text-align: right; padding-right: 0"><mtext mathvariant="normal">average:</mtext><mspace width="0.222em"></mspace></mtd><mtd columnalign="left" style="text-align: left; padding-left: 0"><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>U</mi><mo>,</mo><mi>V</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mstyle displaystyle="false"><mfrac><mn>1</mn><mrow><mo stretchy="false" form="prefix">|</mo><mi>U</mi><mo stretchy="false" form="prefix">|</mo><mo stretchy="false" form="prefix">|</mo><mi>V</mi><mo stretchy="false" form="prefix">|</mo></mrow></mfrac></mstyle><munder><mo>∑</mo><mrow><mi>u</mi><mo>,</mo><mi>v</mi></mrow></munder><mi>ρ</mi><mo stretchy="false" form="prefix">(</mo><mi>u</mi><mo>,</mo><mi>v</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo></mtd><mtd columnalign="right" style="text-align: right; padding-right: 0"><mtext mathvariant="normal">ward:</mtext><mspace width="0.222em"></mspace></mtd><mtd columnalign="left" style="text-align: left; padding-left: 0"><mrow><mtext mathvariant="normal">прирост </mtext><mspace width="0.333em"></mspace></mrow><mi>Q</mi><mrow><mspace width="0.333em"></mspace><mtext mathvariant="normal"> при слиянии</mtext></mrow><mi>.</mi></mtd></mtr></mtable><annotation encoding="application/x-tex">\n\\begin{aligned}\n\\text{single:}\\ &amp; R(U,V) = \\min_{u \\in U, v \\in V}\\rho(u,v), &amp;\n\\text{complete:}\\ &amp; R(U,V) = \\max_{u,v}\\rho(u,v),\\\\\n\\text{average:}\\ &amp; R(U,V) = \\tfrac{1}{|U||V|}\\textstyle\\sum_{u,v}\\rho(u,v), &amp;\n\\text{ward:}\\ &amp; \\text{прирост } Q \\text{ при слиянии}.\n\\end{aligned}\n</annotation></semantics></math></p>\n<p>Ваш вариант: <code>variant[&quot;linkage&quot;]</code>. Постройте дендрограмму\nи сравните все четыре способа.</p>\n</div>\n<div id="cell020" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy.cluster.hierarchy <span class="im">import</span> dendrogram, fcluster, linkage <span class="im">as</span> scipy_linkage</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) для четырёх linkage постройте дендрограммы и соответствующие разбиения</span></span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a><span class="co">#          на 3 кластера, посчитайте ARI;</span></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) воспроизведите «эффект цепочки»: две вытянутые полосы плюс десяток</span></span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a><span class="co">#          точек-мостика между ними. Какие linkage склеивают полосы, а какие нет?</span></span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;linkage вашего варианта:&quot;</span>, variant[<span class="st">&quot;linkage&quot;</span>])</span></code></pre></div>\n</div>\n<div id="cell021" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Как выглядят дендрограммы разных linkage и\nчем они отличаются? Какой linkage пострадал от эффекта цепочки и почему?\nКогда это свойство оказывается полезным?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell022" class="cell markdown">\n<hr />\n<h1 id="часть-6-своя-выборка">Часть 6. Своя выборка</h1>\n<p>Кластеризуйте признаковое описание своей выборки\n(<strong>без</strong> использования целевой переменной!) и проверьте,\nсвязаны ли найденные кластеры с целью. Это типичный разведочный\nсценарий: кластеры могут отражать сегменты, которые полезно\nрассматривать отдельно.</p>\n</div>\n<div id="cell023" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant, return_frame<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) кластеризуйте признаки (без целевой переменной!) для K = 2..8,</span></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a><span class="co">#          посчитайте Q, силуэт, BIC и AMI найденного разбиения с целью;</span></span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) выберите K, постройте таблицу «кластер x класс» (доли по строкам)</span></span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a><span class="co">#          и размеры кластеров;</span></span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) выведите центры кластеров по 8 наиболее различающимся признакам</span></span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a><span class="co">#          и объясните содержательно, чем кластеры отличаются.</span></span></code></pre></div>\n</div>\n<div id="cell024" class="cell markdown">\n<h2 id="итоги-работы">Итоги работы</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Почему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nвсегда сходится, но не обязательно к глобальному минимуму? Приведите\nконфигурацию из четырёх точек и\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">K=2</annotation></semantics></math>,\nгде неудачная инициализация даёт неоптимальный ответ.</li>\n<li>Функционал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>\nмонотонно убывает по\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>.\nОзначает ли это, что «чем больше кластеров, тем лучше»? Как правильно\nпоставить вопрос о выборе\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>?</li>\n<li>Теорема 7.7 гарантирует, что\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>L</mi></mrow><annotation encoding="application/x-tex">\\ln L</annotation></semantics></math>\nне убывает. Гарантирует ли она сходимость к глобальному максимуму\nправдоподобия? Что делают на практике?</li>\n<li>У вас данные из двух вытянутых, почти параллельных полос. Какой\nметод кластеризации вы возьмёте и почему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nне подойдёт?</li>\n<li>Силуэт указал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">K=2</annotation></semantics></math>,\nBIC —\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">K=5</annotation></semantics></math>.\nВаши действия?</li>\n</ol>\n<h3 id="домашнее-задание">Домашнее задание</h3>\n<ol>\n<li><p><strong>EM с неполными данными.</strong> Обобщите свою реализацию\nEM на случай пропусков в признаках: на E-шаге ответственности считаются\nпо наблюдаемым координатам (маргинальная плотность гауссианы — тоже\nгауссиана), на M-шаге пропущенные значения заменяются условным ожиданием\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>𝔼</mi><mo stretchy="false" form="prefix">[</mo><msub><mi>x</mi><mtext mathvariant="normal">miss</mtext></msub><mo>∣</mo><msub><mi>x</mi><mtext mathvariant="normal">obs</mtext></msub><mo>,</mo><mi>k</mi><mo stretchy="false" form="postfix">]</mo></mrow><annotation encoding="application/x-tex">\\mathbb{E}[x_{\\text{miss}} \\mid x_{\\text{obs}}, k]</annotation></semantics></math>.\nПроверьте на своей выборке из работы 1 (там пропуски есть по\nпостроению): сравните качество восстановления пропущенных значений с\n<code>SimpleImputer(strategy=&#39;median&#39;)</code> по среднему квадрату\nошибки на искусственно скрытых значениях.</p></li>\n<li><p><strong>Устойчивость кластеризации как критерий выбора\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>.</strong>\nРеализуйте подход, основанный на устойчивости: для каждого\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>\n50 раз возьмите случайные 80 % объектов, кластеризуйте и измерьте,\nнасколько согласованы разбиения на пересечении подвыборок (ARI между\nпарами). Постройте график средней согласованности от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>\nи сравните выбор с силуэтом и BIC на данных из части 4. Обоснуйте,\nпочему устойчивость — разумный критерий именно для задачи без\nучителя.</p></li>\n</ol>\n</div>\n</body>\n</html>\n'}}]);